from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock) -> None:
        self._capacity = max(0, int(capacity))
        self._ttl = ttl
        self._clock = clock
        self._data = OrderedDict()
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def put(self, key, value) -> None:
        if self._capacity <= 0:
            return

        now = self._clock()

        if key in self._data:
            self._data[key] = (value, now + self._ttl)
            self._data.move_to_end(key)
        else:
            if len(self._data) >= self._capacity:
                self._purge_expired(now)
                if len(self._data) >= self._capacity:
                    self._data.popitem(last=False)
                    self._evictions += 1

            self._data[key] = (value, now + self._ttl)

    def get(self, key, default=None):
        entry = self._data.get(key)

        if entry is None:
            self._misses += 1
            return default

        now = self._clock()
        value, expiry = entry

        if expiry <= now:
            del self._data[key]
            self._expirations += 1
            self._misses += 1
            return default

        self._data.move_to_end(key)
        self._hits += 1
        return value

    def __len__(self) -> int:
        if not self._data:
            return 0

        now = self._clock()
        return sum(1 for _, expiry in self._data.values() if expiry > now)

    def stats(self) -> dict[str, int]:
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def _purge_expired(self, now) -> None:
        expired_keys = [key for key, (_, expiry) in self._data.items() if expiry <= now]

        for key in expired_keys:
            del self._data[key]
            self._expirations += 1
