import re
from decimal import Decimal, ROUND_HALF_UP

_AMOUNT_RE = re.compile(
    r"[+-]?(?:(?:[0-9]{1,3}(?:,[0-9]{3})*|[0-9]+)(?:\.[0-9]+)?|\.[0-9]+)"
)


def _parse_amount(value) -> Decimal | None:
    if value is None:
        return None

    s = str(value).strip()
    if not s:
        return None

    s = s.replace("$", "")
    s = "".join(s.split())

    if not _AMOUNT_RE.fullmatch(s):
        return None

    return Decimal(s.replace(",", ""))


def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    if n <= 0:
        return []

    totals: dict[str, tuple[str, Decimal]] = {}

    for row in rows:
        customer = row.get("customer")
        if customer is None:
            continue

        name = str(customer).strip()
        if not name:
            continue

        amount = _parse_amount(row.get("amount"))
        if amount is None:
            continue

        key = name.casefold()
        if key in totals:
            display_name, current_total = totals[key]
            totals[key] = (display_name, current_total + amount)
        else:
            totals[key] = (name, amount)

    cent = Decimal("0.01")
    rounded_totals: list[tuple[str, Decimal]] = []

    for name, total in totals.values():
        rounded = total.quantize(cent, rounding=ROUND_HALF_UP)
        if rounded == 0:
            rounded = Decimal("0.00")
        rounded_totals.append((name, rounded))

    rounded_totals.sort(key=lambda item: (-item[1], item[0]))

    return [(name, float(total)) for name, total in rounded_totals[:n]]
